current_wls = None

def killWLSession(session: wls):
  print("Stopping session: ", session.kernel) 
  # try:
  #   session.evaluate(wlexpr("Interrupt[]"), timeout=4)
  # except Exception as e:
  #   print(f"Abort failed: {e}")
  # print("Abort succeeded")
  try:
    session.terminate()
    session.stop()
  except Exception as e:
    print(f"Terminate/Stop failed: {e}")
  print("Session stopped")

def safe_exit(*args, **kwargs):
  if current_wls:
    killWLSession(current_wls)
  raise SystemExit
  
builtins.exit = safe_exit
builtins.quit = safe_exit

@contextmanager
def wls_session(kernel_path="C:\\Program Files\\Wolfram Research\\Wolfram\\14.3\\WolframKernel.exe",
                package_folder="./compModels",
                package_name="CompositionErrorEstimation",
                model_folder="./compModels",
                linear_delay=28.0156,
                ext_height=0.2,
                ext_width=0.8):
  global current_wls
  try:
    if current_wls is None:
      print("Starting up session")
      session = wls(kernel=kernel_path)
      current_wls = session

      print("Loading package and initializing model")
      session.evaluate(wlexpr(f'Get["{package_folder}/{package_name}.wl"]'))
      session.evaluate(wl.__getattr__(package_name).InitializeModel(model_folder, linear_delay, ext_height, ext_width))
    yield current_wls
  finally:
    if current_wls is not None:
      print("Closing session context")
      # killWLSession(current_wls)

